  backend=call;Text=T("RockPro | Propozycje zakupowe","RockPro | Purchase proposals");Size=new Size(1380,930);MinimumSize=new Size(1120,760);Font=new Font("Segoe UI",10);AutoScaleMode=AutoScaleMode.Dpi;
  BackColor=Color.FromArgb(242,246,249);Padding=new Padding(18);StartPosition=FormStartPosition.CenterParent;
