  heading.Dock=DockStyle.Fill;heading.Padding=new Padding(10);heading.BackColor=Color.FromArgb(255,235,214);root.Controls.Add(heading,0,0);
  var toolbar=new TableLayoutPanel {Dock=DockStyle.Fill,ColumnCount=4,RowCount=1,Padding=new Padding(0,6,0,0)};for(int i=0;i<3;i++)toolbar.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,200));toolbar.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));
  foreach(var button in new[]{load,calculate,export}){button.Dock=DockStyle.Fill;button.Margin=new Padding(0,0,8,8);button.BackColor=Color.White;}calculate.BackColor=Color.FromArgb(237,102,21);calculate.ForeColor=Color.White;
  toolbar.Controls.Add(load,0,0);toolbar.Controls.Add(calculate,1,0);toolbar.Controls.Add(export,2,0);sourceLabel.Dock=DockStyle.Fill;sourceLabel.AutoEllipsis=true;sourceLabel.Padding=new Padding(8,10,0,0);toolbar.Controls.Add(sourceLabel,3,0);root.Controls.Add(toolbar,0,1);
