  var body=new TableLayoutPanel {Dock=DockStyle.Fill,RowCount=2,ColumnCount=1};body.RowStyles.Add(new RowStyle(SizeType.Percent,36));body.RowStyles.Add(new RowStyle(SizeType.Percent,64));body.Controls.Add(requirements,0,0);
  optionTab.Controls.Add(options);allocationTab.Controls.Add(allocations);problemTab.Controls.Add(problems);offerTab.Controls.Add(offers);sourceTab.Controls.Add(sources);tabs.TabPages.AddRange(new[]{optionTab,allocationTab,problemTab,offerTab,sourceTab});tabs.Dock=DockStyle.Fill;body.Controls.Add(tabs,0,1);root.Controls.Add(body,0,3);
  status.Dock=DockStyle.Fill;status.Padding=new Padding(0,8,0,0);root.Controls.Add(status,0,4);
