  calculate.Click+=async delegate{await Calculate();};export.Click+=delegate{using(var dialog=new SaveFileDialog {Filter="JSON (*.json)|*.json",FileName="propozycja-zakupow.json",OverwritePrompt=true})if(dialog.ShowDialog(this)==DialogResult.OK)try{ExportDraft(dialog.FileName);}catch(Exception ex){lastFailure=ex.Message;Describe();}};
  requirements.SelectionChanged+=delegate{if(!rendering)ShowLine();};asOfDate.ValueChanged+=delegate{InputChanged();};asOfDate.MouseUp+=delegate{InputChanged();};asOfDate.KeyUp+=delegate{InputChanged();};currency.TextChanged+=delegate{InputChanged();};cash.TextChanged+=delegate{InputChanged();};surplus.ValueChanged+=delegate{InputChanged();};
  FormClosing+=delegate(object sender,FormClosingEventArgs e){if(busy)e.Cancel=true;};UiText.LanguageChanged+=RefreshLanguage;FormClosed+=delegate{UiText.LanguageChanged-=RefreshLanguage;};RefreshLanguage(null,EventArgs.Empty);UpdateButtons();
 }
 static DataGridView Grid(){var grid=new DataGridView {Dock=DockStyle.Fill,ReadOnly=true,AllowUserToAddRows=false,AllowUserToDeleteRows=false,RowHeadersVisible=false,MultiSelect=false,SelectionMode=DataGridViewSelectionMode.FullRowSelect,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,AutoSizeRowsMode=DataGridViewAutoSizeRowsMode.AllCells,ColumnHeadersHeightSizeMode=DataGridViewColumnHeadersHeightSizeMode.AutoSize,BackgroundColor=Color.White};grid.DefaultCellStyle.WrapMode=DataGridViewTriState.True;grid.DefaultCellStyle.Padding=new Padding(4,6,4,6);grid.DefaultCellStyle.SelectionBackColor=Color.FromArgb(255,229,208);grid.DefaultCellStyle.SelectionForeColor=Color.FromArgb(35,47,60);return grid;}
 static void Columns(DataGridView grid,string[] captions){if(grid.Columns.Count==0)for(int i=0;i<captions.Length;i++){int n=grid.Columns.Add("c"+i,captions[i]);grid.Columns[n].MinimumWidth=65;}for(int i=0;i<captions.Length;i++)grid.Columns[i].HeaderText=captions[i];}
 void PolicyField(FlowLayoutPanel panel,string title,Control control){var label=new Label {Text=title,AutoSize=true,Margin=new Padding(0,6,5,0)};captions.Add(label);panel.Controls.Add(label);control.Margin=new Padding(0,0,14,0);panel.Controls.Add(control);}
 static string Value(Dictionary<string,object> row,string key){if(!row.ContainsKey(key)||row[key]==null)return "—";var formatted=row[key] as IFormattable;return formatted!=null?formatted.ToString(null,CultureInfo.InvariantCulture):Convert.ToString(row[key]);}
 static string Unit(string key){return key=="piece"?T("szt.","piece"):key=="sheet"?T("arkusz","sheet"):key;}
 static string Reason(string key){switch(key){case "incomplete_offer":return T("Niepełna oferta","Incomplete quote");case "late_arrival":return T("Dostawa po terminie","Late arrival");case "insufficient_confirmed_availability":return T("Za mała potwierdzona dostępność","Insufficient confirmed availability");case "surplus_limit":return T("Limit nadwyżki","Surplus limit");case "cash_limit":return T("Limit gotówki","Cash limit");case "quote_not_current":return T("Oferta poza ważnością","Quote not current");case "currency_conversion_not_configured":return T("Brak kursu waluty","Currency conversion unavailable");default:return key;}}
 static string Reasons(object rows){return String.Join("; ",Array.ConvertAll(Rpc.Rows(rows),x=>Reason(Convert.ToString(x))));}
 static string MissingFields(object rows){return String.Join(", ",Array.ConvertAll(Rpc.Rows(rows),x=>{switch(Convert.ToString(x)){case "id":return "ID";case "item_id":return T("Materiał / SKU","Item / SKU");case "supplier":return T("Dostawca","Supplier");case "unit":return T("Jednostka","Unit");case "currency":return T("Waluta","Currency");case "quote_date":return T("Data oferty","Quote date");case "valid_until":return T("Ważna do","Valid until");case "pack_size":return T("Paczka","Pack");case "moq":return "MOQ";case "lead_days":return T("Dni dostawy","Lead days");case "available_quantity":return T("Dostępność","Availability");case "price_breaks":return T("Progi cenowe","Price breaks");case "shipping_net":return T("Transport netto","Shipping net");case "tax_percent":return T("Podatek [%]","Tax [%]");default:return Convert.ToString(x);}}));}
 static string PriceBreaks(object rows){var values=new List<string>();foreach(var item in Rpc.Rows(rows)){var tier=Rpc.Obj(item);values.Add(T("od ","from ")+Value(tier,"min_quantity")+": "+Value(tier,"unit_net"));}return values.Count==0?"—":String.Join("\n",values.ToArray());}
 void UpdateButtons(){bool ready=document!=null;load.Enabled=!busy;calculate.Enabled=!busy&&ready;export.Enabled=!busy&&result!=null;foreach(Control c in new Control[]{asOfDate,currency,cash,surplus})c.Enabled=!busy&&ready;requirements.Enabled=tabs.Enabled=!busy;}
 void InputChanged(){if(loading||busy)return;result=policyUsed=null;calculatedAt=null;lastFailure="";Render();Describe();UpdateButtons();}
 void LoadDocument(string path){
  document=result=policyUsed=null;inputPath=fileSha="";calculatedAt=null;lastFailure="";Render();UpdateButtons();
  byte[] bytes;using(var reader=new BinaryReader(File.OpenRead(path)))bytes=reader.ReadBytes(2097153);if(bytes.Length>2097152)throw new Exception(T("Plik wejściowy przekracza 2 MiB.","Input file exceeds 2 MiB."));int offset=bytes.Length>=3&&bytes[0]==239&&bytes[1]==187&&bytes[2]==191?3:0;
  var data=Rpc.Obj(json.DeserializeObject(new UTF8Encoding(false,true).GetString(bytes,offset,bytes.Length-offset)));
  if(data.Count!=3||!data.ContainsKey("requirements")||!data.ContainsKey("offers")||!data.ContainsKey("policy"))throw new Exception(T("Wymagany zestaw requirements, offers i policy.","An exact requirements, offers and policy bundle is required."));
  var needs=Rpc.Obj(data["requirements"]);if(needs.Count!=3||!needs.ContainsKey("scope")||!needs.ContainsKey("bindings")||!needs.ContainsKey("lines")||!(needs["lines"] is object[])||!(needs["bindings"] is object[])||!(data["offers"] is object[]))throw new Exception(T("Nieprawidłowa struktura zapotrzebowania lub ofert.","Invalid requirements or quote structure."));
  foreach(var item in Rpc.Rows(needs["lines"])){var line=Rpc.Obj(item);if(!new HashSet<string>(line.Keys).SetEquals(new[]{"id","item_id","unit","quantity","required_date"}))throw new Exception(T("Wiersz zapotrzebowania ma niepełne lub nieznane pola.","Requirement row has missing or unknown fields."));}
  var p=Rpc.Obj(data["policy"]);DateTime date;if(!DateTime.TryParseExact(Rpc.Str(p,"as_of_date"),"yyyy-MM-dd",CultureInfo.InvariantCulture,DateTimeStyles.None,out date))throw new Exception(T("Data bilansu musi mieć format YYYY-MM-DD.","Balance date must use YYYY-MM-DD."));
  object n=p["max_surplus_units"];if(!(n is int)&&!(n is long))throw new Exception(T("Limit nadwyżki musi być liczbą całkowitą.","Surplus limit must be an integer."));decimal limit=Convert.ToDecimal(n);if(limit<0||limit>1000000)throw new Exception(T("Limit nadwyżki poza zakresem.","Surplus limit out of range."));
  loading=true;try{asOfDate.Value=date;asOfDate.Checked=true;currency.Text=Rpc.Str(p,"currency");cash.Text=p["max_cash_gross"]==null?"":Value(p,"max_cash_gross");surplus.Value=limit;}finally{loading=false;}
  document=data;inputPath=Path.GetFullPath(path);using(var sha=SHA256.Create())fileSha=BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();Render();Describe();UpdateButtons();
 }
 Dictionary<string,object> CurrentPolicy(){if(!asOfDate.Checked)throw new Exception(T("Zaznacz datę bilansu.","Check the balance date."));var p=RevisionUi.Clone(Rpc.Obj(document["policy"]));p["as_of_date"]=asOfDate.Value.ToString("yyyy-MM-dd",CultureInfo.InvariantCulture);p["currency"]=currency.Text.Trim();p["max_cash_gross"]=cash.Text.Trim();p["max_surplus_units"]=(int)surplus.Value;return p;}
 async Task Calculate(){
  if(System.Threading.Thread.CurrentThread.ManagedThreadId!=uiThread)throw new InvalidOperationException("Purchase UI must start on its owner thread");System.Threading.SynchronizationContext.SetSynchronizationContext(new WindowsFormsSynchronizationContext());if(busy||document==null)return;
  result=policyUsed=null;calculatedAt=null;lastFailure="";busy=true;UpdateButtons();Render();status.Text=T("Obliczanie propozycji z bieżącego magazynu…","Calculating proposals from current inventory…");
  try{var policy=CurrentPolicy();var request=new Dictionary<string,object>{{"requirements",RevisionUi.Clone(Rpc.Obj(document["requirements"]))},{"offers",document["offers"]},{"policy",policy}};
   var reply=await Task.Run(()=>backend("preview_purchases",request));if(!Object.Equals(reply["proposal_only"],true)||!Object.Equals(reply["orders_placed"],false)||!Object.Equals(reply["production_approved"],false))throw new Exception(T("Odpowiedź nie potwierdza zakresu samej propozycji.","Response does not confirm proposal-only scope."));
   result=reply;policyUsed=policy;calculatedAt=DateTime.UtcNow;Render();
  }catch(Exception ex){lastFailure=ex.Message;result=policyUsed=null;Render();}finally{busy=false;UpdateButtons();Describe();}
 }
 void Describe(){sourceLabel.Text=inputPath.Length==0?T("Brak pliku wejściowego","No input file"):Path.GetFileName(inputPath);status.ForeColor=lastFailure.Length>0?Color.Firebrick:Color.FromArgb(55,75,95);
  if(lastFailure.Length>0){status.Text=lastFailure+(result==null?T("\nWynik nie został przyjęty. Eksport jest zablokowany.","\nThe result was not accepted. Export is blocked."):T("\nNie zapisano pliku; bieżąca propozycja pozostaje do wglądu.","\nThe file was not saved; the current proposal remains available for review."));return;}
  string state=document==null?T("Wczytaj własne zapotrzebowanie, oferty i limity. Dane nie są uzupełniane z domysłów.","Load requirements, quotes and limits. Missing inputs are never invented."):result==null?T("Dane wczytane lub zmienione — użyj Przelicz. Wartości nie są jeszcze sprawdzone przez solver.","Inputs loaded or changed — use Calculate. The solver has not checked these values yet."):T("Propozycja obliczona, bez akceptacji i bez zamówień. Wybierz wiersz zapotrzebowania, aby porównać opcje.","Draft calculated without approval or orders. Select a requirement row to compare options.");
  string scope=document!=null?Rpc.Str(Rpc.Obj(document["requirements"]),"scope"):"";status.Text=(scope=="synthetic_test"?T("TEST SYNTETYCZNY • ","SYNTHETIC TEST • "):scope=="source_input"?T("DANE OPERATORA • ","OPERATOR INPUT • "):"")+state+"\n"+T("Limit gotówki i transport są liczone osobno dla opcji. Wspólny koszyk i transport zbiorczy nie są zatwierdzone. Magazyn pochodzi z bieżącego odczytu.","Cash limits and shipping apply per option. A combined basket and consolidated shipping are not approved. Inventory is read at calculation time.");
 }
 void Render(){rendering=true;try{requirements.Rows.Clear();options.Rows.Clear();allocations.Rows.Clear();problems.Rows.Clear();offers.Rows.Clear();sources.Text="";if(document==null)return;
  if(result==null)foreach(var item in Rpc.Rows(Rpc.Obj(document["requirements"])["lines"])){var row=Rpc.Obj(item);requirements.Rows.Add(Value(row,"id"),Value(row,"item_id"),Unit(Value(row,"unit")),row["quantity"],Value(row,"required_date"),"—","—",T("Nieobliczone","Not calculated"));}
  else foreach(var item in Rpc.Rows(result["lines"])){var row=Rpc.Obj(item);var need=Rpc.Obj(row["requirement"]);var preferred=Rpc.Obj(row["preferred_option"]);int index=requirements.Rows.Add(Value(need,"id"),Value(need,"item_id"),Unit(Value(need,"unit")),need["quantity"],Value(need,"required_date"),row["shortage"],preferred.Count==0?"—":preferred["quantity"],Convert.ToInt64(row["shortage"])==0?T("Pokryte zapasem/dostawą","Covered by stock/supply"):preferred.Count==0?T("Brak dopuszczonej opcji","No feasible option"):T("Opcja wiersza do oceny","Line option for review"));requirements.Rows[index].Tag=row;}
  foreach(var item in Rpc.Rows(document["offers"])){var row=Rpc.Obj(item);offers.Rows.Add(Value(row,"id"),Value(row,"item_id"),Value(row,"supplier"),Unit(Value(row,"unit")),Value(row,"currency"),Value(row,"quote_date"),Value(row,"valid_until"),Value(row,"pack_size"),Value(row,"moq"),Value(row,"lead_days"),Value(row,"available_quantity"),Value(row,"shipping_net"),Value(row,"tax_percent"),row.ContainsKey("price_breaks")?PriceBreaks(row["price_breaks"]):"—");}
  if(result!=null)foreach(var item in Rpc.Rows(result["offer_issues"])){var row=Rpc.Obj(item);problems.Rows.Add(T("Zestaw ofert","Quote bundle"),Convert.ToInt32(row["offer_index"])+1,Value(row,"offer_id"),Reason(Value(row,"reason")),MissingFields(row["missing_fields"]));}
  sources.Text=T("PLIK ŹRÓDŁOWY: ","SOURCE FILE: ")+inputPath+"\r\nSHA256: "+fileSha+"\r\n\r\n"+T("POWIĄZANIA WEJŚĆ:\r\n","INPUT BINDINGS:\r\n")+json.Serialize(Rpc.Obj(document["requirements"])["bindings"])+"\r\n\r\n"+T("POLITYKA ŹRÓDŁOWA (zmiany w polach wymagają przeliczenia):\r\n","SOURCE POLICY (edited fields require recalculation):\r\n")+json.Serialize(document["policy"]);
  if(result!=null)sources.Text+="\r\n\r\n"+T("POLITYKA UŻYTA:\r\n","POLICY USED:\r\n")+json.Serialize(policyUsed)+"\r\nInput SHA256: "+Value(result,"input_sha256")+"\r\nProposal SHA256: "+Value(result,"proposal_sha256")+"\r\nUTC: "+calculatedAt.Value.ToString("o");
  requirements.ClearSelection();requirements.CurrentCell=null;
 }finally{rendering=false;}}
 void ShowLine(){options.Rows.Clear();allocations.Rows.Clear();if(result==null||requirements.SelectedRows.Count==0)return;var selected=Rpc.Obj(requirements.SelectedRows[0].Tag);var need=Rpc.Obj(selected["requirement"]);
  foreach(var item in Rpc.Rows(selected["options"])){var row=Rpc.Obj(item);int index=options.Rows.Add(Value(row,"offer_id"),Value(row,"supplier"),row["quantity"],row["surplus"],Value(row,"unit_net"),Value(row,"shipping_net"),Value(row,"total_net"),Value(row,"total_gross"),Value(row,"currency"),Value(row,"arrival_date"),Convert.ToBoolean(row["feasible"])?T("Dopuszczona do oceny","Feasible for review"):Reasons(row["restrictions"]));options.Rows[index].Cells[10].Style.BackColor=Convert.ToBoolean(row["feasible"])?Color.FromArgb(222,240,227):Color.FromArgb(249,224,220);}
  foreach(var item in Rpc.Rows(selected["allocations"])){var row=Rpc.Obj(item);allocations.Rows.Add(Value(row,"supply_id"),Value(row,"kind")=="free_stock"?T("Wolny stan","Free stock"):T("Potwierdzona dostawa","Confirmed supply"),row["quantity"],Unit(Value(need,"unit")),Value(row,"available_date"));}
  // The global issue list stays visible even when an incomplete quote has no SKU.
  problems.Rows.Clear();foreach(var item in Rpc.Rows(result["offer_issues"])){var row=Rpc.Obj(item);problems.Rows.Add(T("Zestaw ofert","Quote bundle"),Convert.ToInt32(row["offer_index"])+1,Value(row,"offer_id"),Reason(Value(row,"reason")),MissingFields(row["missing_fields"]));}
  foreach(var item in Rpc.Rows(selected["rejected_offers"])){var row=Rpc.Obj(item);problems.Rows.Add(Value(need,"id"),"—",Value(row,"offer_id"),Reason(Value(row,"reason")),row.ContainsKey("missing_fields")?MissingFields(row["missing_fields"]):"—");}options.ClearSelection();
 }
 void ExportDraft(string path){if(result==null||policyUsed==null)throw new Exception(T("Najpierw oblicz aktualną propozycję.","Calculate a current proposal first."));var output=new Dictionary<string,object>{{"schema_version",1},{"kind","purchase_proposal_draft"},{"source_file",Path.GetFileName(inputPath)},{"source_sha256",fileSha},{"calculated_at_utc",calculatedAt.Value.ToString("o")},{"policy_used",policyUsed},{"requirements",document["requirements"]},{"offers",document["offers"]},{"result",result},{"orders_placed",false},{"production_approved",false}};using(var stream=new FileStream(path,FileMode.CreateNew,FileAccess.Write))using(var writer=new StreamWriter(stream,new UTF8Encoding(false)))writer.Write(json.Serialize(output));}
 void RefreshLanguage(object sender,EventArgs e){if(IsDisposed)return;Text=T("RockPro | Propozycje zakupowe","RockPro | Purchase proposals");heading.Text=T("ROCKPRO • PROPOZYCJE ZAKUPÓW — BEZ ZAMAWIANIA\nZapotrzebowanie + bieżący magazyn + potwierdzone dostawy + oferty → porównanie pełnych kosztów, nadwyżek i terminów.\nArkusze wymagają SKU formatu z rozkroju. Lista zamienników pochodzi z wejścia operatora; program nie zatwierdza nowych zamienników.","ROCKPRO • PURCHASE PROPOSALS — NO ORDERING\nRequirements + current inventory + confirmed supplies + quotes → compare full costs, surplus and dates.\nSheets require a cut-plan format SKU. Substitutions come from operator input; the program does not approve new substitutes.");
  load.Text=T("Wczytaj dane…","Load inputs…");calculate.Text=T("Przelicz propozycje","Calculate proposals");export.Text=T("Eksportuj szkic…","Export draft…");foreach(var caption in captions)caption.Text=LayoutLanguage.Translate(caption.Text);
  optionTab.Text=T("Opcje zakupowe","Purchase options");allocationTab.Text=T("Pokrycie zapasu / dostaw","Stock / supply coverage");problemTab.Text=T("Braki i odrzucone oferty","Missing / rejected quotes");offerTab.Text=T("Oferty wejściowe","Input quotes");sourceTab.Text=T("Źródła i polityka","Sources and policy");
  Columns(requirements,new[]{T("Wymaganie","Requirement"),T("Materiał / SKU","Item / SKU"),T("Jednostka","Unit"),T("Potrzeba","Demand"),T("Termin","Required date"),T("Brakuje","Shortage"),T("Ilość opcji wiersza","Line option quantity"),T("Stan propozycji","Proposal status")});
  Columns(options,new[]{T("Oferta","Quote"),T("Dostawca","Supplier"),T("Ilość","Quantity"),T("Nadwyżka","Surplus"),T("Cena netto / j.","Unit net"),T("Transport netto","Shipping net"),T("Całość netto","Total net"),T("Całość brutto","Total gross"),T("Waluta","Currency"),T("Dostawa","Arrival"),T("Ograniczenia","Restrictions")});
  Columns(allocations,new[]{T("Źródło","Source"),T("Rodzaj","Kind"),T("Ilość","Quantity"),T("Jednostka","Unit"),T("Dostępne od","Available from")});
  Columns(problems,new[]{T("Dotyczy","Scope"),T("Pozycja w pliku","Position in file"),T("Oferta","Quote"),T("Powód","Reason"),T("Brakujące pola","Missing fields")});
  Columns(offers,new[]{"ID",T("Materiał / SKU","Item / SKU"),T("Dostawca","Supplier"),T("Jednostka","Unit"),T("Waluta","Currency"),T("Data oferty","Quote date"),T("Ważna do","Valid until"),T("Paczka","Pack"),"MOQ",T("Dni kalendarzowe","Calendar days"),T("Dostępność","Availability"),T("Transport netto","Shipping net"),T("Podatek [%]","Tax [%]"),T("Progi cenowe (netto)","Price breaks (net)")});Render();Describe();UpdateButtons();
 }
